:root {
  --bg: #f6f1e8;
  --surface: #fffaf2;
  --surface-2: #efe4d1;
  --text: #2f2419;
  --text-soft: #6c5d4b;
  --primary: #1f6b47;
  --primary-2: #2f8a5d;
  --accent: #7a4b2a;
  --line: #dac9b2;
  --shadow: 0 10px 30px rgba(58, 39, 23, 0.12);
  --radius: 18px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: "DM Sans", "Inter", system-ui, sans-serif;
  background: radial-gradient(circle at 85% 10%, #efe7da 0%, var(--bg) 40%);
  color: var(--text);
  line-height: 1.5;
}
a { color: inherit; text-decoration: none; }
.container { width: min(1160px, 92%); margin: 0 auto; }
.section { padding: 64px 0; }
.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 0;
  cursor: pointer;
  padding: 12px 18px;
  border-radius: 999px;
  font-weight: 700;
  transition: .25s ease;
}
.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-2); transform: translateY(-1px); }
.btn-outline { border: 1px solid var(--primary); color: var(--primary); background: #fff; }
.btn-outline:hover { background: #f0f8f3; }
.site-header {
  position: sticky; top: 0; z-index: 40;
  backdrop-filter: blur(8px);
  background: rgba(246, 241, 232, .85);
  border-bottom: 1px solid var(--line);
}
.nav-wrap { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 0; }
.brand { display: flex; align-items: center; gap: 12px; font-weight: 800; }
.logo {
  width: 38px; height: 38px; border-radius: 50%;
  background: linear-gradient(145deg, #3a8f63, #1f6b47);
  display: grid; place-items: center; color: #fff; font-size: 18px;
}
.nav-links { display: flex; gap: 14px; align-items: center; flex-wrap: wrap; }
.nav-links a { padding: 8px 12px; border-radius: 999px; font-weight: 600; color: var(--text-soft); }
.nav-links a.active, .nav-links a:hover { background: #ece2d3; color: var(--text); }
.hero {
  display: grid;
  grid-template-columns: 1.1fr .9fr;
  gap: 26px;
  align-items: stretch;
}
.hero-copy { padding: 34px; }
.kicker { letter-spacing: .12em; text-transform: uppercase; color: var(--primary); font-weight: 700; font-size: 12px; }
h1, h2, h3, h4 {
  font-family: "Plus Jakarta Sans", "DM Sans", sans-serif;
  line-height: 1.1;
  margin: 12px 0;
}
h1 { font-size: clamp(2rem, 4.2vw, 3.6rem); }
h2 { font-size: clamp(1.6rem, 2.6vw, 2.4rem); }
.lead { font-size: 1.06rem; color: var(--text-soft); max-width: 56ch; }
.hero-art {
  border-radius: var(--radius);
  background: linear-gradient(160deg, rgba(31,107,71,.95), rgba(122,75,42,.85));
  min-height: 360px;
  position: relative;
  overflow: hidden;
}
.hero-art::before, .hero-art::after {
  content: ""; position: absolute; border-radius: 50%;
  background: rgba(255,255,255,.18);
}
.hero-art::before { width: 240px; height: 240px; top: -40px; right: -30px; }
.hero-art::after { width: 180px; height: 180px; bottom: -30px; left: -30px; }
.media-note { position: absolute; left: 20px; bottom: 20px; color: #fff; font-weight: 600; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 18px; }
.tile { padding: 20px; }
.meta { color: var(--text-soft); font-size: .95rem; }
.footer {
  margin-top: 60px;
  border-top: 1px solid var(--line);
  background: #ece0cd;
}
.footer-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px; padding: 34px 0; }
.footer-col h4 { margin: 0 0 10px; font-size: 1rem; }
.footer-col a { display: block; padding: 6px 0; color: #5e4d3c; font-size: .95rem; }
.foot-bottom { border-top: 1px solid #d3c0a5; padding: 14px 0 24px; color: #6b5b49; font-size: .9rem; }
.footer-toggle { display: none; }
.cookie {
  position: fixed; left: 20px; right: 20px; bottom: 20px; z-index: 60;
  background: #2f2419; color: #fff; border-radius: 16px;
  padding: 14px 16px; display: flex; align-items: center; justify-content: space-between; gap: 10px;
}
.tabs { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 14px; }
.tab-btn { padding: 10px 14px; border-radius: 999px; border: 1px solid var(--line); background: #fff; cursor: pointer; font-weight: 700; }
.tab-btn.active { background: var(--primary); color: #fff; border-color: var(--primary); }
.tab-panel { display: none; padding: 20px; }
.tab-panel.active { display: block; }
.carousel { position: relative; overflow: hidden; }
.carousel-track { display: flex; transition: transform .4s ease; }
.carousel-slide { min-width: 100%; padding: 18px; }
.carousel-controls { display: flex; gap: 8px; margin-top: 10px; }
.icon-btn { width: 38px; height: 38px; border-radius: 50%; border: 1px solid var(--line); background: #fff; cursor: pointer; }
.menu-layout { display: grid; grid-template-columns: 240px 1fr; gap: 20px; }
.sidebar { padding: 18px; position: sticky; top: 88px; align-self: start; }
.sidebar a { display: block; padding: 9px 10px; border-radius: 10px; color: var(--text-soft); font-weight: 600; }
.sidebar a:hover { background: #f3eadc; color: var(--text); }
.store-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.map { min-height: 420px; background: linear-gradient(145deg,#dfcfb7,#c9b08f); border-radius: var(--radius); position: relative; }
.pin { position: absolute; width: 16px; height: 16px; background: var(--primary); border-radius: 50%; border: 2px solid #fff; }
.suggest { margin-top: 8px; border: 1px solid var(--line); border-radius: 12px; background: #fff; display: none; }
.suggest.active { display: block; }
.suggest button { width: 100%; text-align: left; border: 0; background: transparent; padding: 10px 12px; cursor: pointer; }
.toggle-pill { display: inline-flex; background: #f3e8d8; border-radius: 999px; padding: 4px; }
.toggle-pill button { border: 0; background: transparent; padding: 8px 14px; border-radius: 999px; cursor: pointer; font-weight: 700; color: #6e5f4e; }
.toggle-pill button.active { background: #fff; color: var(--text); }
@media (max-width: 900px) {
  .hero, .grid-3, .grid-2, .store-grid, .menu-layout { grid-template-columns: 1fr; }
  .sidebar { position: static; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-col .links { display: none; }
  .footer-col.open .links { display: block; }
  .footer-toggle { display: inline-block; float: right; }
  .nav-links { gap: 8px; }
}
EOF

cat > /app/output/script.js << 'EOF'
const $ = (s, p = document) => p.querySelector(s);
const $$ = (s, p = document) => [...p.querySelectorAll(s)];

(function cookieBanner() {
  const btn = $('#cookieAgree');
  const banner = $('#cookieBanner');
  if (!btn || !banner) return;
  if (localStorage.getItem('gb_cookie_ok') === '1') banner.style.display = 'none';
  btn.addEventListener('click', () => {
    localStorage.setItem('gb_cookie_ok', '1');
    banner.style.display = 'none';
  });
})();

(function footerAccordion() {
  if (window.innerWidth > 900) return;
  $$('.footer-col').forEach((col) => {
    const toggle = $('.footer-toggle', col);
    if (!toggle) return;
    toggle.addEventListener('click', () => col.classList.toggle('open'));
  });
})();

(function rewardsTabs() {
  const wrap = $('#rewardsTabs');
  if (!wrap) return;
  const buttons = $$('.tab-btn', wrap);
  const panels = $$('.tab-panel', wrap.parentElement);
  buttons.forEach((button) => {
    button.addEventListener('click', () => {
      buttons.forEach((item) => item.classList.remove('active'));
      panels.forEach((panel) => panel.classList.remove('active'));
      button.classList.add('active');
      const id = button.dataset.tab;
      const panel = document.getElementById(id);
      if (panel) panel.classList.add('active');
    });
  });
})();

function setupCarousel(rootId) {
  const root = document.getElementById(rootId);
  if (!root) return;
  const track = $('.carousel-track', root);
  const slides = $$('.carousel-slide', root);
  const prev = $('.prev', root.parentElement);
  const next = $('.next', root.parentElement);
  let index = 0;
  const move = () => { track.style.transform = `translateX(-${index * 100}%)`; };
  next?.addEventListener('click', () => { index = (index + 1) % slides.length; move(); });
  prev?.addEventListener('click', () => { index = (index - 1 + slides.length) % slides.length; move(); });
}
setupCarousel('featuredCarousel');
$$('[data-carousel]').forEach((node) => setupCarousel(node.id));

(function storeLocator() {
  const input = $('#storeSearch');
  const suggest = $('#suggestions');
  const filterBtn = $('#filterBtn');
  const panel = $('#filterPanel');
  const results = $('#storeResults');
  if (!input) return;
  const places = ['Seattle, WA', 'Portland, OR', 'San Diego, CA', 'Austin, TX'];
  input.addEventListener('input', () => {
    const q = input.value.toLowerCase().trim();
    suggest.innerHTML = '';
    if (!q) { suggest.classList.remove('active'); return; }
    places.filter((item) => item.toLowerCase().includes(q)).forEach((place) => {
      const btn = document.createElement('button');
      btn.textContent = place;
      btn.onclick = () => {
        input.value = place;
        suggest.classList.remove('active');
        results.innerHTML = `<strong>Showing stores near ${place}</strong><p class="meta">3 stores with fast pickup and 2 with delivery.</p>`;
      };
      suggest.appendChild(btn);
    });
    suggest.classList.add('active');
  });
  filterBtn?.addEventListener('click', () => panel.hidden = !panel.hidden);

  const orderBtns = $$('.order-type button');
  orderBtns.forEach((button) => {
    button.addEventListener('click', () => {
      orderBtns.forEach((item) => item.classList.remove('active'));
      button.classList.add('active');
      const mode = button.dataset.mode;
      results.innerHTML = `<strong>${mode} stores selected</strong><p class="meta">Updated results for ${mode.toLowerCase()} availability.</p>`;
    });
  });
})();
EOF

